// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 10);
        vm.assume(v > 0 && v < 1e30);
        // Record balances before transfer
        uint256[] memory before = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
            vm.assume(success && data.length == 32);
            before[i] = abi.decode(data, (uint256));
        }
        // Call transfer
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result);
        // Verify balances increased by v each
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
            if (success && data.length == 32) {
                uint256 after = abi.decode(data, (uint256));
                assertTrue(after == before[i] + v, "balance should increase by v");
            }
        }
    }
}

