pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Record balances before
        uint256[] memory beforeBalances = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            // Assuming the token contract at caddress has a public balanceOf function
            (bool success, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            if (success) {
                beforeBalances[i] = abi.decode(data, (uint256));
            } else {
                beforeBalances[i] = 0;
            }
        }
        // Call transfer
        c.transfer(from, caddress, _tos, v);
        // Record balances after
        uint256 totalIncrease = 0;
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            uint256 after;
            if (success) {
                after = abi.decode(data, (uint256));
            } else {
                after = 0;
            }
            totalIncrease += (after - beforeBalances[i]);
        }
        assertTrue(totalIncrease == v * _tos.length);
    }
}

