pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0) && from != address(c));
        // Ensure all recipients are distinct to avoid double-counting
        for (uint i = 0; i < _tos.length; i++) {
            for (uint j = i + 1; j < _tos.length; j++) {
                vm.assume(_tos[i] != _tos[j]);
            }
        }
        uint256[] memory balancesBefore = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            balancesBefore[i] = _tos[i].balance;
        }
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        require(success);
        uint256 totalIncrease = 0;
        for (uint i = 0; i < _tos.length; i++) {
            uint256 increase = _tos[i].balance - balancesBefore[i];
            totalIncrease += increase;
        }
        assertTrue(totalIncrease == v * _tos.length);
    }
}

