pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, address[] memory tos, uint256 v) public {
        // Bound v and tos length to avoid out-of-gas / unrealistic
        vm.assume(tos.length > 0 && tos.length <= 10);
        v = bound(v, 0, 1e30);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        // We need to simulate a token contract that can succeed or fail.
        // We deploy a simple token that tracks whether transferFrom should revert.
        Token token = new Token();
        address tokenAddr = address(token);

        // Pre-compute which calls would fail by random chance (here all succeed)
        // To make the test meaningful, we can set one of the tos to trigger a revert.
        // But for a general rule, we need to let the fuzzer control behavior.
        // We'll use a helper: the test will set token's shouldRevert flag based on fuzz params.
        // However the mutation changes require(_s) to require(!_s).
        // The general rule: transfer reverts iff any inner call fails.
        // But since we want to distinguish, we need inner calls to sometimes succeed and sometimes fail.
        // We can implement this by using an address that when called with transferFrom selector,
        // reverts with a specific condition. Simpler: create an ERC20 mock that stores a mapping of from->tos->amount.
        // But for Foundry test, we can use vm.etch to deploy a mock that behaves according to a flag.

        // Instead, we'll use a simple approach: deploy a contract that always reverts on transferFrom
        // and another that always succeeds, and mix them in tos array.
        address successAddr = address(new AlwaysSucceed());
        address failAddr = address(new AlwaysFail());

        // Build the tos array with alternating success/fail based on a fuzz parameter.
        // Let's use the first element of tos to decide: if tos[0] is even-indexed, use success; else fail.
        // But that's too deterministic. Better: use the fuzz param 'from' to decide a flag.
        // Simpler: assume all calls should succeed for the reference to not revert.
        // Then the rule: for reference, transfer never reverts. For mutant, if any call succeeds, transfer reverts.
        // This matches the given bug.

        // Since we cannot control whether transferFrom succeeds without an actual contract,
        // we deploy a token that we control: it returns success unless we pre-approve and transfer.
        // To keep it simple: we test with an address that will always succeed.
        // The reference always succeeds; mutant always fails because it requires !_s.
        // Then the rule: for reference, transfer returns true (no revert); for mutant, it reverts.
        // But the assertion must be a general rule that holds for C and breaks for M.
        // Since M always reverts if the call succeeds, the rule "transfer does not revert" holds for C (if all calls succeed) and fails for M.

        // Ensure all inner calls will succeed: use an address that implements transferFrom and returns true.
        address mockToken = address(new MockERC20());

        // Now call transfer
        bool reverted;
        try c.transfer(from, mockToken, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: For reference C, transfer should not revert (since we always succeed).
        assertTrue(!reverted, "transfer should not revert");
    }
}

// Helper contracts (defined outside InvMutTest but within same file, not imported)
contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract AlwaysSucceed {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract AlwaysFail {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("fail");
    }
}

